/* generated by the ABI test: structs of awkward sizes passed between a C host and C² scripts.
   Windows: MIR passes 3, 5, 6 and 7-byte structs in a register, MSVC by reference (a known gap). */
#define ABI_ALL(X) \
    X(S1) \
    X(S2) \
    X(S4) \
    X(S8) \
    X(F2) \
    X(FI) \
    X(D1) \
    X(I3) \
    X(F3) \
    X(S16) \
    X(D2) \
    X(DL) \
    X(ID) \
    X(F4) \
    X(FFD) \
    X(I5) \
    X(S24) \
    X(D3) \
    X(D4) \
    X(CD) \
    ABI_UNIX(X)
#ifdef _WIN32
#define ABI_UNIX(X)
#else
#define ABI_UNIX(X) X(S3) X(S5) X(S6) X(S7)
#endif

typedef struct { char a; } S1;
static S1 make_S1(int seed) { S1 v; v.a = (char)(seed * 3 + 1); return v; }
static long long sum_S1(S1 v) { return (long long)v.a * 1; }
